   <script>
     const faqs = [
       {
         question: "Why do cats purr?",
         answer: "Cats often purr when they feel relaxed, but purring can also happen when they are nervous, healing, or asking for attention. Context matters: posture, appetite, and behavior tell the fuller story."
       },
       {
         question: "How much sleep do cats need?",
         answer: "Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even more because growth, play, and age all increase their need for rest."
       },
       {
         question: "Should cats be kept indoors?",
         answer: "Indoor cats are generally safer from traffic, predators, parasites, and infectious disease. Enrichment such as climbing spaces, window perches, puzzle feeders, and daily play helps indoor cats stay active and curious."
       },
       {
         question: "Why does my cat knead blankets?",
         answer: "Kneading is a comforting behavior that begins in kittenhood. Many cats keep doing it as adults when they feel secure, content, or ready to settle in for a nap."
       },
       {
         question: "How often should cats visit a veterinarian?",
         answer: "Healthy adult cats usually benefit from a wellness visit at least once a year. Kittens, senior cats, and cats with medical conditions may need more frequent care based on a veterinarian's guidance."
       }
     ];

     const escapeHtml = (value) =>
       value.replace(/[&<>"']/g, (character) => ({
         "&": "&amp;",
         "<": "&lt;",
         ">": "&gt;",
         '"': "&quot;",
         "'": "&#39;"
       }[character]));

     function FAQItem({ question, answer }, index) {
       const buttonId = `faq-question-${index + 1}`;
       const detailsId = `faq-answer-${index + 1}`;

       return `
         <div class="example">
           <h2>
             <button
               class="question-button"
               id="${buttonId}"
               type="button"
               aria-expanded="false"
               aria-controls="${detailsId}"
             >
               ${escapeHtml(question)}
             </button>
           </h2>
           <div
             class="details"
             id="${detailsId}"
             role="region"
             aria-labelledby="${buttonId}"
             aria-hidden="true"
           >
             <p>${escapeHtml(answer)}</p>
           </div>
         </div>
       `;
     }

     function FAQList({ items }) {
       return `<section class="faq-list" aria-label="Cat questions and answers">${items.map(FAQItem).join("")}</section>`;
     }

     function App() {
       return `
         <div class="page-shell">
           <header>
             <p class="eyebrow">Curious cat care</p>
             <h1>Cat FAQ</h1>
             <p class="intro">Quick answers for common questions about feline behavior, health routines, and happy indoor living.</p>
           </header>
           <main id="main-content" tabindex="-1">
             <div class="faq-card">
               ${FAQList({ items: faqs })}
             </div>
           </main>
           <footer>
             <p>For sudden behavior changes or health concerns, contact a veterinarian.</p>
           </footer>
         </div>
       `;
     }

     document.querySelector("#root").innerHTML = App();

     document.querySelectorAll(".question-button").forEach((button) => {
       button.addEventListener("click", () => {
         const details = document.getElementById(button.getAttribute("aria-controls"));
         const isExpanded = button.getAttribute("aria-expanded") === "true";

         button.setAttribute("aria-expanded", String(!isExpanded));
         details.setAttribute("aria-hidden", String(isExpanded));
       });
     });
   </script>
 </body>
